using EEMS.SharedKernel.Domain;
namespace EEMS.Modules.Teams.Domain;
public sealed class TeamTask:Entity<Guid>
{
    private TeamTask(){}private TeamTask(Guid id,Guid tenantId,Guid electionId,Guid? teamId,Guid? assigneeUserId,short stateId,short priorityId,string title,DateTimeOffset? dueAtUtc){if(tenantId==Guid.Empty||electionId==Guid.Empty)throw new ArgumentException("Tenant and election are required.");if(teamId is null&&assigneeUserId is null)throw new ArgumentException("A team or user assignee is required.");if(stateId<=0||priorityId<=0)throw new ArgumentOutOfRangeException(nameof(stateId));Id=id;TenantId=tenantId;ElectionId=electionId;TeamId=teamId;AssigneeUserId=assigneeUserId;StateId=stateId;PriorityId=priorityId;Title=Text(title,200);DueAtUtc=dueAtUtc;CreatedAtUtc=DateTimeOffset.UtcNow;Version=1;}
    public Guid TenantId{get;private set;}public Guid ElectionId{get;private set;}public Guid? TeamId{get;private set;}public Guid? AssigneeUserId{get;private set;}public short StateId{get;private set;}public short PriorityId{get;private set;}public string Title{get;private set;}=string.Empty;public DateTimeOffset? DueAtUtc{get;private set;}public DateTimeOffset CreatedAtUtc{get;private set;}public int Version{get;private set;}
    public static TeamTask Create(Guid tenantId,Guid electionId,Guid? teamId,Guid? userId,short stateId,short priorityId,string title,DateTimeOffset? dueAtUtc=null)=>new(Guid.NewGuid(),tenantId,electionId,teamId,userId,stateId,priorityId,title,dueAtUtc);public void MoveTo(short stateId){if(stateId<=0)throw new ArgumentOutOfRangeException(nameof(stateId));StateId=stateId;Version++;}private static string Text(string v,int m){var t=v?.Trim()??string.Empty;return t.Length is >0&&t.Length<=m?t:throw new ArgumentException("Value is invalid.");}
}
